import React, { useEffect, useState } from 'react';
import { getCurrentOrder, removeOrderItem, saveOrder, makeOrder } from '../year_api/YearApi';

export default function OrderPage() {
  const [order, setOrder] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [histText, setHistText] = useState('');
  const [confidences, setConfidences] = useState<Record<string, string>>({});

  useEffect(() => {
    let mounted = true;
    getCurrentOrder().then(data => {
      if (!mounted) return;
      if (data.order === null) {
        setOrder(null);
        setLoading(false);
        return;
      }
      setOrder(data);
      setHistText(data.history_text || '');
      const conf: Record<string, string> = {};
      (data.items || []).forEach((it: any) => conf[`confidence_${it.person_id}`] = String(it.percent_of_trust || 1));
      setConfidences(conf);
      setLoading(false);
    }).catch(() => { setOrder(null); setLoading(false); });
    return () => { mounted = false };
  }, []);

  if (loading) return <div className="cart-container"><p>Загрузка...</p></div>;
  if (!order) return <div className="cart-container"><p>У вас нет текущей заявки.</p></div>;

  const handleRemove = async (itemId: number) => {
    if (!confirm('Удалить элемент?')) return;
    await removeOrderItem(itemId);
    const updated = await getCurrentOrder();
    setOrder(updated);
  }

  const handleSave = async () => {
    const payload: any = { history_text: histText };
    for (const k in confidences) payload[k] = confidences[k];
    await saveOrder(order.order_id, payload);
    alert('Сохранено');
  }

  const handleMake = async () => {
    const confPayload: any = {};
    for (const k in confidences) confPayload[k] = confidences[k];
    const res = await makeOrder(order.order_id, confPayload);
    if (res.ok) {
      alert(`Результат: ${res.year_from_result} — ${res.year_to_result}`);
      const updated = await getCurrentOrder();
      setOrder(updated);
    } else {
      alert('Ошибка при расчёте');
    }
  }

  return (
    <div className="cart-container">
      <h2 className="page-title">Текущая заявка</h2>

      {order.items.map((it: any) => (
        <div key={it.id} className="cart-card">
          <div className="cart-card-content">
            <h2>{it.person_name}</h2>
            <p className="years">{it.year_from} — {it.year_to}</p>
            <div className="confidence-input-container">
              <label className="confidence-label">Доверие
                <input className="confidence-input" type="number" min="0" max="1" step="0.01" value={confidences[`confidence_${it.person_id}`] || '1'} onChange={e => setConfidences({...confidences, [`confidence_${it.person_id}`]: e.target.value})} />
              </label>
            </div>
          </div>
          <button className="remove-btn" onClick={() => handleRemove(it.id)}>✖</button>
        </div>
      ))}

      <div className="card-footer">
        <label>Текст хроники</label>
        <textarea value={histText} onChange={e => setHistText(e.target.value)} />

        <div className="order-buttons">
          <button className="save-btn" onClick={handleSave}>Сохранить</button>
          <button className="make-order-btn" onClick={handleMake}>Сформировать</button>
        </div>

        <div className="event-year">
          <h2>Результат</h2>
          <div className="year-box">{order.year_from_result || '—'} — {order.year_to_result || '—'}</div>
        </div>
      </div>
    </div>
  );
}
